//! 🎟️ Original actor input and paid authorities remain in place across admitted turns.
use crate::retained_turn::{RetainedTurnInput,OriginalActorTurnWork};
use semio_framework_async::{CancelToken,CancelTokenRetirement,CancelTokenRetirementError};
use semio_framework_job::{Generation,JobPayloadAuthority,OperationId,OriginalCallerSourceParent,StepBudget,StepContext};
use semio_framework_value::{RetainedCloneGrant,RetainedCloneProgress,RetainedCloneStep,RetirementDemand,ValueError,ValueRefusalKind};
use std::mem::ManuallyDrop;

#[derive(Clone,Copy,Debug,PartialEq,Eq)]
pub struct OriginalActorAdmission{pub ready:bool,pub progress:RetainedCloneProgress}
#[derive(Debug)]
pub enum OriginalActorContextError{Refused(ValueError),Cancellation(CancelTokenRetirementError)}
/// 🧳️ Owns the same input until dispatch and borrows the same admitted root and payload ledger.
pub struct OriginalActorContext<T>{input:ManuallyDrop<Option<T>>,identity:Option<(OperationId,Generation)>,epoch:u64,work:OriginalActorTurnWork,work_units_spent:u128,initial_grant:RetainedCloneGrant,issued_grant:RetainedCloneGrant,physical_spent:RetainedCloneProgress,epoch_physical_start:RetainedCloneProgress,clock:Option<fn()->Option<u64>>,cancel:ManuallyDrop<Option<CancelToken>>,payload:ManuallyDrop<Option<JobPayloadAuthority>>,cancel_close:ManuallyDrop<Option<CancelTokenRetirement>>,source:ManuallyDrop<Option<OriginalCallerSourceParent>>,sequence:u64,ready:bool,closing:bool}
impl<T> OriginalActorContext<T>{
 pub fn new(input:T,retained:RetainedTurnInput)->Result<Self,(ValueError,T)>{if let Err(error)=retained.validate(){return Err((error,input))}Ok(Self{input:ManuallyDrop::new(Some(input)),identity:Some((OperationId(retained.operation),Generation(retained.generation))),epoch:0,work:retained.work,work_units_spent:0,initial_grant:retained.grant,issued_grant:retained.grant,physical_spent:Default::default(),epoch_physical_start:Default::default(),clock:None,cancel:ManuallyDrop::new(None),payload:ManuallyDrop::new(None),cancel_close:ManuallyDrop::new(None),source:ManuallyDrop::new(None),sequence:0,ready:false,closing:false})}
 pub fn input(&self)->Option<&T>{self.input.as_ref()}
 pub fn original_work_units_spent(&self)->u128{self.work_units_spent}
 pub fn remaining_work(&self)->Result<OriginalActorTurnWork,ValueError>{let spent=u64::try_from(self.work_units_spent).map_err(|_|refusal("original actor actual work exceeds u64 source fuel"))?;let fuel=self.work.fuel.checked_sub(spent).ok_or_else(||refusal("original actor actual work exceeds declared total source fuel"))?;Ok(OriginalActorTurnWork{fuel,..self.work})}
 pub fn remaining_grant(&self)->Result<RetainedCloneGrant,ValueError>{if !self.physical_spent.fits(self.initial_grant){return Err(refusal("original physical receipt exceeds its initial source authority"))}Ok(RetainedCloneGrant{maximum_items:self.initial_grant.maximum_items-self.physical_spent.copied_items,maximum_copy_bytes:self.initial_grant.maximum_copy_bytes-self.physical_spent.copied_bytes,maximum_capacity_bytes:self.initial_grant.maximum_capacity_bytes-self.physical_spent.retained_capacity_bytes,maximum_release_bytes:self.initial_grant.maximum_release_bytes-self.physical_spent.released_bytes,maximum_depth:self.initial_grant.maximum_depth})}
 fn record_physical(&mut self,progress:RetainedCloneProgress)->Result<(),ValueError>{self.physical_spent=self.physical_spent.checked_add(progress)?;self.remaining_grant()?;Ok(())}
 fn validate_policy(input:RetainedTurnInput,policy:RetainedCloneGrant)->Result<(),ValueError>{if !subset(policy,input.grant){return Err(refusal("original call policy exceeds supplied total authority"))}Ok(())}
 fn permits(grant:semio_framework_value::RetainedCloneGrant,demand:RetirementDemand)->bool{grant.maximum_items!=0&&grant.maximum_copy_bytes>=demand.copy_bytes&&grant.maximum_capacity_bytes>=demand.capacity_bytes&&grant.maximum_release_bytes>=demand.release_bytes&&grant.maximum_depth>=demand.depth}
 fn validate(&self,retained:RetainedTurnInput)->Result<(),ValueError>{retained.validate()?;if (retained.epoch==self.epoch&&retained.grant!=self.issued_grant)||(retained.epoch!=self.epoch&&!subset(retained.grant,self.remaining_grant()?)){return Err(refusal("original actor context renewed its physical source authority"))}if self.identity!=Some((OperationId(retained.operation),Generation(retained.generation))){return Err(refusal("original actor context identity differs from supplied input"))}if (retained.epoch==self.epoch&&retained.work!=self.work)||retained.work.clock_binding!=self.work.clock_binding||retained.work.absolute_deadline_us!=self.work.absolute_deadline_us||(retained.epoch!=self.epoch&&u128::from(retained.work.fuel)>u128::from(self.work.fuel).checked_sub(self.work_units_spent).ok_or_else(||refusal("original actor work exceeds its total original fuel"))?){return Err(refusal("original actor context changed its issuer clock/deadline or renewed work"))}Ok(())}
 fn begin(&mut self,retained:RetainedTurnInput)->Result<(),ValueError>{self.validate(retained)?;if retained.epoch<=self.epoch{return Err(refusal("original actor context turn epoch was already used"))}self.epoch=retained.epoch;self.work=retained.work;self.issued_grant=retained.grant;self.epoch_physical_start=self.physical_spent;self.work_units_spent=0;Ok(())}
 /// 🌱️ One caller-funded root or ledger birth yields before any semantic producer.
 pub fn admit_step(&mut self,retained:RetainedTurnInput,policy:RetainedCloneGrant,clock:fn()->Option<u64>)->Result<OriginalActorAdmission,ValueError>{Self::validate_policy(retained,policy)?;let result=self.admit_inner(retained,policy,clock);let progress=match &result{Ok(step)=>step.progress,Err(error)=>error.retained_progress()};self.record_physical(progress)?;result}
 fn admit_inner(&mut self,retained:RetainedTurnInput,policy:RetainedCloneGrant,clock:fn()->Option<u64>)->Result<OriginalActorAdmission,ValueError>{if retained.work.fuel==0||clock().is_none_or(|now|now>=retained.work.absolute_deadline_us){return Ok(OriginalActorAdmission{ready:false,progress:Default::default()})}if self.clock.is_some_and(|original|!std::ptr::fn_addr_eq(original,clock)){return Err(refusal("original actor admission substituted its issuer clock callback"))}let demand=if self.source.is_some(){RetirementDemand{depth:1,..Default::default()}}else if self.cancel.is_none(){CancelToken::root_admission_demands()}else if self.payload.is_none(){JobPayloadAuthority::admission_demand()}else{OriginalCallerSourceParent::admission_demand()};if !Self::permits(policy,demand){return Ok(OriginalActorAdmission{ready:false,progress:Default::default()})}self.begin(retained)?;self.work_units_spent=1;self.clock=Some(clock);if self.closing{return Err(refusal("original actor context is closing"))}if self.source.is_none(){if self.cancel.is_none(){let Some((original,progress))=CancelToken::admit_root(policy)?else{return Ok(OriginalActorAdmission{ready:false,progress:Default::default()})};*self.cancel=Some(original);return Ok(OriginalActorAdmission{ready:false,progress})}if self.payload.is_none(){let(operation,generation)=self.identity.unwrap();let Some((original,progress))=JobPayloadAuthority::admit(operation,generation,policy)?else{return Ok(OriginalActorAdmission{ready:false,progress:Default::default()})};*self.payload=Some(original);return Ok(OriginalActorAdmission{ready:false,progress})}let demand=OriginalCallerSourceParent::admission_demand();let grant=policy;if grant.maximum_items==0||grant.maximum_capacity_bytes<demand.capacity_bytes||grant.maximum_depth<demand.depth{return Ok(OriginalActorAdmission{ready:false,progress:Default::default()})}let payload=self.payload.take().unwrap();let cancel=self.cancel.take().unwrap();return match OriginalCallerSourceParent::admit(payload,cancel,grant){Ok((source,progress))=>{*self.source=Some(source);Ok(OriginalActorAdmission{ready:false,progress})},Err((error,payload,cancel))=>{*self.payload=Some(payload);*self.cancel=Some(cancel);Err(error)}}}if policy.maximum_items==0||policy.maximum_depth==0{return Ok(OriginalActorAdmission{ready:false,progress:Default::default()})}self.ready=true;Ok(OriginalActorAdmission{ready:true,progress:RetainedCloneProgress{copied_items:1,..Default::default()}})}
 /// 🤝️ Lends the persistent original receipt and returns only the actual call delta externally.
 pub fn borrow_context<'a>(&'a mut self,retained:RetainedTurnInput,budget:StepBudget,recipient:&'a mut RetainedCloneProgress,clock:fn()->Option<u64>)->Result<StepContext<'a>,ValueError>{self.validate(retained)?;if !self.ready||self.closing||retained.epoch!=self.epoch||!subset(budget.retained,retained.grant)||u128::from(budget.fuel)>u128::from(retained.work.fuel).checked_sub(self.work_units_spent).ok_or_else(||refusal("original borrowed work exceeds its original total"))?||budget.deadline_us>retained.work.absolute_deadline_us||self.clock.is_some_and(|original|!std::ptr::fn_addr_eq(original,clock)){return Err(refusal("original actor context loan differs from admitted turn"))}let source=self.source.as_ref().ok_or_else(||refusal("original actor parent source has not been admitted"))?;let total=self.remaining_work()?;let epoch_spent=RetainedCloneProgress{copied_items:self.physical_spent.copied_items-self.epoch_physical_start.copied_items,copied_bytes:self.physical_spent.copied_bytes-self.epoch_physical_start.copied_bytes,retained_capacity_bytes:self.physical_spent.retained_capacity_bytes-self.epoch_physical_start.retained_capacity_bytes,released_bytes:self.physical_spent.released_bytes-self.epoch_physical_start.released_bytes};let remaining=retained.return_original(epoch_spent,u64::try_from(self.work_units_spent).map_err(|_|refusal("original epoch work exceeds u64"))?)?.remaining;let mut cx=source.borrow_context(StepBudget::new(total.fuel,total.absolute_deadline_us,self.initial_grant),clock,&mut self.sequence,&mut self.physical_spent)?;cx.bind_original_source_epoch(retained.epoch)?;cx.bind_original_clock_binding(retained.work.clock_binding)?;cx.bind_original_retained_total(remaining)?;cx.narrow_original_work_budget(budget)?;cx.bind_original_physical_recipient(recipient)?;cx.bind_original_work_recipient(&mut self.work_units_spent)?;Ok(cx)}
 /// ▶️ A dispatched turn borrows already admitted authorities under its next original epoch.
 pub fn begin_dispatch(&mut self,retained:RetainedTurnInput)->Result<(),ValueError>{if !self.ready||self.closing{return Err(refusal("original actor context has not reached paid readiness"))}self.begin(retained)}
 /// 📬️ Moves the original input once into its semantic consumer after both births yielded.
 pub fn take_input(&mut self)->Result<Option<T>,ValueError>{if !self.ready||self.closing||self.source.is_none(){return Err(refusal("original actor input cannot dispatch before paid authorities"))}Ok(self.input.take())}
 pub fn terminal_is_empty(&self)->bool{self.input.is_none()&&self.identity.is_none()&&self.cancel.is_none()&&self.payload.is_none()&&self.cancel_close.is_none()&&self.source.is_none()}
 pub fn original_loans_are_returned(&self)->bool{self.source.as_ref().is_none_or(OriginalCallerSourceParent::original_loans_are_returned)}
 /// 📏️ Quotes one original physical frontier or one separate enclosing metadata removal.
 pub fn retirement_demands(&self)->Result<RetirementDemand,ValueError>{if self.input.is_some(){return Err(refusal("original actor input still requires its semantic owner"))}if let Some(source)=self.source.as_ref(){if !source.terminal_is_empty(){return source.retirement_demands()}return Ok(RetirementDemand{depth:1,..Default::default()})}if let Some(payload)=self.payload.as_ref(){if !payload.terminal_is_empty(){return Ok(payload.retirement_demands())}return Ok(RetirementDemand{depth:1,..Default::default()})}if self.cancel.is_some(){return Ok(RetirementDemand{depth:1,..Default::default()})}if let Some(cancel)=self.cancel_close.as_ref(){if !cancel.terminal_is_empty(){return cancel.retirement_demands()}return Ok(RetirementDemand{depth:1,..Default::default()})}Ok(RetirementDemand{depth:usize::from(self.identity.is_some()),..Default::default()})}
 /// ♻️ Each original authority closes before its separate inline removal turn.
 pub fn close_step(&mut self,retained:RetainedTurnInput,policy:RetainedCloneGrant)->Result<RetainedCloneStep,OriginalActorContextError>{Self::validate_policy(retained,policy).map_err(OriginalActorContextError::Refused)?;let result=self.close_inner(retained,policy);let progress=match &result{Ok(step)=>step.progress(),Err(OriginalActorContextError::Refused(error))|Err(OriginalActorContextError::Cancellation(CancelTokenRetirementError::Refused(error)))=>error.retained_progress(),Err(_)=>Default::default()};self.record_physical(progress).map_err(OriginalActorContextError::Refused)?;result}
 fn close_inner(&mut self,retained:RetainedTurnInput,policy:RetainedCloneGrant)->Result<RetainedCloneStep,OriginalActorContextError>{if self.terminal_is_empty(){return Ok(RetainedCloneStep::Complete(Default::default()))}self.validate(retained).map_err(OriginalActorContextError::Refused)?;let demand=self.retirement_demands().map_err(OriginalActorContextError::Refused)?;let grant=policy;if retained.work.fuel==0||!Self::permits(grant,demand){return Ok(RetainedCloneStep::Progress(Default::default()))}self.begin(retained).map_err(OriginalActorContextError::Refused)?;self.work_units_spent=1;self.closing=true;if let Some(source)=self.source.as_mut(){if !source.terminal_is_empty(){return source.close_step(grant).map(|step|RetainedCloneStep::Progress(step.progress())).map_err(OriginalActorContextError::Refused)}drop(self.source.take());return Ok(metadata(false))}if let Some(payload)=self.payload.as_mut(){if !payload.terminal_is_empty(){return payload.close_step(grant).map(|step|RetainedCloneStep::Progress(step.progress())).map_err(OriginalActorContextError::Refused)}drop(self.payload.take());return Ok(metadata(false))}if let Some(cancel)=self.cancel.take(){*self.cancel_close=Some(CancelTokenRetirement::from_token(cancel));return Ok(metadata(false))}if let Some(cancel)=self.cancel_close.as_mut(){if !cancel.terminal_is_empty(){return cancel.close_step(grant).map(|step|RetainedCloneStep::Progress(step.progress())).map_err(OriginalActorContextError::Cancellation)}drop(self.cancel_close.take());return Ok(metadata(false))}self.identity=None;Ok(metadata(true))}
}
fn subset(a:RetainedCloneGrant,b:RetainedCloneGrant)->bool{a.maximum_items<=b.maximum_items&&a.maximum_copy_bytes<=b.maximum_copy_bytes&&a.maximum_capacity_bytes<=b.maximum_capacity_bytes&&a.maximum_release_bytes<=b.maximum_release_bytes&&a.maximum_depth<=b.maximum_depth}
fn metadata(complete:bool)->RetainedCloneStep{let progress=RetainedCloneProgress{copied_items:1,..Default::default()};if complete{RetainedCloneStep::Complete(progress)}else{RetainedCloneStep::Progress(progress)}}
fn refusal(message:&'static str)->ValueError{ValueError::literal(ValueRefusalKind::InvariantViolated,message)}
impl<T> Drop for OriginalActorContext<T>{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"original actor context reached Drop before paid authority retirement");}}

