/// 🧾️ Physical effects remain attached to the original input on semantic success or failure.
pub struct OriginalActorCall<T,E>{pub input:RetainedTurnInput,pub receipt_spent:RetainedCloneProgress,pub work_units_spent:u64,pub result:Result<T,E>}
impl<T,E> OriginalActorCall<T,E>{pub fn receipt(&self)->Result<crate::retained_turn::RetainedTurnReceipt,ValueError>{self.input.return_original(self.receipt_spent,self.work_units_spent)}}
#[derive(Debug)]
pub enum OriginalActorCallError<E>{Authority(ValueError),Semantic(E)}
/// 🏛️ Holds one persistent guest context until its original authorities and binding have paid closure.
pub struct OriginalActorContextSlot{context:ManuallyDrop<Option<OriginalActorContext<()>>>,binding:Option<(u64,u64,u64)>}
impl OriginalActorContextSlot{
 pub const fn empty()->Self{Self{context:ManuallyDrop::new(None),binding:None}}
 pub fn validate_next_input(&self,input:RetainedTurnInput)->Result<(),ValueError>{input.validate()?;if let Some((operation,generation,epoch))=self.binding{if input.operation!=operation||input.generation!=generation||input.epoch<=epoch{return Err(refusal("original guest binding differs from original identity or repeats an issued epoch"))}}Ok(())}
 pub fn admit_step(&mut self,input:RetainedTurnInput,policy:RetainedCloneGrant,clock:fn()->Option<u64>)->OriginalActorCall<OriginalActorAdmission,ValueError>{let mut work_units_spent=0;let result=(||{self.validate_next_input(input)?;OriginalActorContext::<()>::validate_policy(input,policy)?;if input.work.fuel==0||clock().is_none_or(|now|now>=input.work.absolute_deadline_us)||policy.maximum_items==0||policy.maximum_depth==0{return Ok(OriginalActorAdmission{ready:false,progress:Default::default()})}if self.context.is_none(){let mut original=OriginalActorContext::new((),input).map_err(|(error,())|error)?;original.begin(input)?;original.clock=Some(clock);work_units_spent=1;original.work_units_spent=1;original.record_physical(RetainedCloneProgress{copied_items:1,..Default::default()})?;*self.context=Some(original);self.binding=Some((input.operation,input.generation,input.epoch));return Ok(OriginalActorAdmission{ready:false,progress:RetainedCloneProgress{copied_items:1,..Default::default()}})}let result=self.context.as_mut().unwrap().admit_step(input,policy,clock);if self.context.as_ref().unwrap().epoch==input.epoch{self.binding=Some((input.operation,input.generation,input.epoch));work_units_spent=u64::try_from(self.context.as_ref().unwrap().work_units_spent).unwrap_or(u64::MAX);}result})();let receipt_spent=match &result{Ok(admission)=>admission.progress,Err(error)=>error.retained_progress()};OriginalActorCall{input,receipt_spent,work_units_spent,result}}
 /// 🤝️ The semantic producer receives the exact caller recipient and both original paid authorities.
 pub fn dispatch_step<T,E>(&mut self,input:RetainedTurnInput,budget:StepBudget,recipient:&mut RetainedCloneProgress,clock:fn()->Option<u64>,produce:impl FnOnce(&mut StepContext<'_>)->Result<T,E>)->OriginalActorCall<T,OriginalActorCallError<E>>{let mut work_units_spent=0;let result=(||{self.validate_next_input(input).map_err(OriginalActorCallError::Authority)?;let original=self.context.as_mut().ok_or_else(||OriginalActorCallError::Authority(refusal("original guest context has not been admitted")))?;if !subset(budget.retained,input.grant)||budget.fuel>input.work.fuel||budget.deadline_us>input.work.absolute_deadline_us{return Err(OriginalActorCallError::Authority(refusal("original guest body budget differs from supplied input")))}original.begin_dispatch(input).map_err(OriginalActorCallError::Authority)?;self.binding=Some((input.operation,input.generation,input.epoch));let mut cx=original.borrow_context(input,budget,recipient,clock).map_err(OriginalActorCallError::Authority)?;let outcome=produce(&mut cx);work_units_spent=u64::try_from(cx.original_work_units_spent()).unwrap_or(u64::MAX);drop(cx);outcome.map_err(OriginalActorCallError::Semantic)})();OriginalActorCall{input,receipt_spent:*recipient,work_units_spent,result}}
 /// 🎟️ Begins one retained callback scope before any asynchronous guest loan leaves it.
 pub fn begin_pending_context(&mut self,input:RetainedTurnInput)->Result<(),ValueError>{self.validate_next_input(input)?;let original=self.context.as_mut().ok_or_else(||refusal("original guest context has not been admitted"))?;original.begin_dispatch(input)?;self.binding=Some((input.operation,input.generation,input.epoch));Ok(())}
 /// 🤝️ Receipt callbacks borrow the same paid source and issued epoch without admitting a replacement turn.
 pub fn borrow_pending_context<'a>(&'a mut self,input:RetainedTurnInput,budget:StepBudget,recipient:&'a mut RetainedCloneProgress,clock:fn()->Option<u64>)->Result<StepContext<'a>,ValueError>{if self.binding!=Some((input.operation,input.generation,input.epoch)){return Err(refusal("original pending context differs from its retained issued scope"))}self.context.as_mut().ok_or_else(||refusal("original pending context has no admitted source"))?.borrow_context(input,budget,recipient,clock)}
 /// 📥️ Accepts one verified epoch for the same pending retirement owner.
 pub fn begin_retirement_input(&mut self,input:RetainedTurnInput)->Result<(),ValueError>{if self.context.is_none(){return Err(refusal("original retirement binding has no admitted context"))}self.validate_next_input(input)?;self.context.as_mut().unwrap().begin(input)?;self.binding=Some((input.operation,input.generation,input.epoch));Ok(())}
 pub fn validate_call_policy(&self,input:RetainedTurnInput,policy:RetainedCloneGrant)->Result<(),ValueError>{OriginalActorContext::<()>::validate_policy(input,policy)}
 pub fn record_pending_physical(&mut self,input:RetainedTurnInput,progress:RetainedCloneProgress)->Result<(),ValueError>{if self.binding!=Some((input.operation,input.generation,input.epoch)){return Err(refusal("original pending physical return differs from its held epoch"))}self.context.as_mut().ok_or_else(||refusal("original pending physical return has no source"))?.record_physical(progress)}
 pub fn record_pending_work(&mut self,input:RetainedTurnInput,work:u64)->Result<(),ValueError>{if self.binding!=Some((input.operation,input.generation,input.epoch)){return Err(refusal("original pending work return differs from its exact held epoch"))}let context=self.context.as_mut().ok_or_else(||refusal("original pending work has no paid source"))?;if context.work!=input.work{return Err(refusal("original pending work return substituted its original work input"))}context.work_units_spent=context.work_units_spent.checked_add(u128::from(work)).ok_or_else(||refusal("original pending work counter overflow"))?;Ok(())}
 /// 🔎️ Observes the admitted original cancellation without copying its root.
 pub fn cancellation_is_cancelled(&self)->Option<bool>{self.context.as_ref().and_then(|context|context.source.as_ref()).and_then(|source|source.cancellation().ok()).map(|cancel|cancel.is_cancelled_now())}
 /// 📏️ Quotes the actual original context frontier independently of semantic body-copy policy.
 pub fn retirement_demands(&self)->Result<RetirementDemand,ValueError>{match self.context.as_ref(){Some(original)if original.input().is_none()&&!original.terminal_is_empty()=>original.retirement_demands(),_=>Ok(RetirementDemand{depth:usize::from(!self.terminal_is_empty()),..Default::default()})}}
 /// ♻️ Empty input removal, physical authorities and enclosing context binding each yield separately.
 pub fn close_step(&mut self,input:RetainedTurnInput,policy:RetainedCloneGrant)->OriginalActorCall<RetainedCloneStep,OriginalActorContextError>{let mut work_units_spent=0;let result=(||{self.validate_next_input(input).map_err(OriginalActorContextError::Refused)?;OriginalActorContext::<()>::validate_policy(input,policy).map_err(OriginalActorContextError::Refused)?;let Some(original)=self.context.as_mut()else{return Ok(RetainedCloneStep::Complete(Default::default()))};original.validate(input).map_err(OriginalActorContextError::Refused)?;if input.work.fuel==0{return Ok(RetainedCloneStep::Progress(Default::default()))}if original.input().is_some(){original.begin(input).map_err(OriginalActorContextError::Refused)?;self.binding=Some((input.operation,input.generation,input.epoch));if policy.maximum_items==0||policy.maximum_depth==0{return Ok(RetainedCloneStep::Progress(Default::default()))}work_units_spent=1;original.work_units_spent=1;original.record_physical(RetainedCloneProgress{copied_items:1,..Default::default()}).map_err(OriginalActorContextError::Refused)?;original.input.take();return Ok(metadata(false))}if !original.terminal_is_empty(){let result=original.close_step(input,policy);if original.epoch==input.epoch{self.binding=Some((input.operation,input.generation,input.epoch));work_units_spent=u64::try_from(original.work_units_spent).unwrap_or(u64::MAX);}return result}self.binding=Some((input.operation,input.generation,input.epoch));if policy.maximum_items==0||policy.maximum_depth==0{return Ok(RetainedCloneStep::Progress(Default::default()))}work_units_spent=1;drop(self.context.take());self.binding=None;Ok(metadata(true))})();let receipt_spent=match &result{Ok(step)=>step.progress(),Err(OriginalActorContextError::Refused(error))|Err(OriginalActorContextError::Cancellation(CancelTokenRetirementError::Refused(error)))=>error.retained_progress(),Err(OriginalActorContextError::Cancellation(CancelTokenRetirementError::Blocked(_)))=>Default::default()};OriginalActorCall{input,receipt_spent,work_units_spent,result}}
 pub fn terminal_is_empty(&self)->bool{self.context.is_none()&&self.binding.is_none()}
 pub fn original_loans_are_returned(&self)->bool{self.context.as_ref().is_none_or(OriginalActorContext::original_loans_are_returned)}
}
impl Drop for OriginalActorContextSlot{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"original guest context slot reached Drop before funded context closure");}}

/// 📥️ Carries the exact original empty admission receipt without transporting refusal prose.
#[derive(Clone,Copy,Debug,PartialEq,Eq,serde::Serialize,serde::Deserialize)]
pub struct OriginalActorAdmissionReply{pub input:RetainedTurnInput,pub spent:RetainedCloneProgress,pub work_units_spent:u64,pub ready:bool,pub refusal:Option<ValueRefusalKind>}
impl OriginalActorAdmissionReply{
 pub fn borrow_original(call:&OriginalActorCall<OriginalActorAdmission,ValueError>)->Self{Self{input:call.input,spent:call.receipt_spent,work_units_spent:call.work_units_spent,ready:call.result.as_ref().is_ok_and(|original|original.ready),refusal:call.result.as_ref().err().map(|original|original.kind)}}
}
/// ♻️ Carries raw original closure effects even when a child is blocked or refuses receipt validation.
#[derive(Clone,Copy,Debug,PartialEq,Eq,serde::Serialize,serde::Deserialize)]
pub struct OriginalActorCloseReply{pub input:RetainedTurnInput,pub spent:RetainedCloneProgress,pub work_units_spent:u64,pub complete:bool,pub blocked:bool,pub refusal:Option<ValueRefusalKind>}
impl OriginalActorCloseReply{
 pub fn borrow_original(call:&OriginalActorCall<RetainedCloneStep,OriginalActorContextError>)->Self{Self{input:call.input,spent:call.receipt_spent,work_units_spent:call.work_units_spent,complete:matches!(&call.result,Ok(RetainedCloneStep::Complete(_))),blocked:matches!(&call.result,Err(OriginalActorContextError::Cancellation(CancelTokenRetirementError::Blocked(_)))),refusal:match &call.result{Err(OriginalActorContextError::Refused(original))|Err(OriginalActorContextError::Cancellation(CancelTokenRetirementError::Refused(original)))=>Some(original.kind),_=>None}}}
}

